insert into public.profile (id, full_name_en, full_name_ar, role_en, role_ar, hero_title_en, hero_title_ar,
insert into public.skills (name_en, name_ar, desc_en, desc_ar, category, color, level, sort_order) values
  ('React.js', 'رياكت جي إس', 'Building and developing interactive, dynamic, and reusable user interfaces using modern component-based architecture.', 'بناء وتطوير واجهات مستخدم تفاعلية، ديناميكية، وقابلة لإعادة الاستخدام باستخدام نظام المكونات الحديث', 'Frontend', '#61dafb', 90, 0),
  ('JavaScript', 'جافا سكريبت', 'Developing and scaling programming logic and advanced web applications with JavaScript.', 'تطوير وتوسيع منطق البرمجة وتطبيقات الويب المتقدمة بلغة جافا سكريبت.', 'Frontend', '#f7df1e', 90, 1),
  ('Supabase', 'سوبابيز', 'Managing databases, authentication, and cloud backend services using Supabase.', 'إدارة قواعد البيانات والتوثيق والخدمات الخلفية السحابية باستخدام Supabase.', 'Backend', '#3ecf8e', 85, 2),
  ('Firebase', 'فيربيس', 'Utilizing Google''s cloud services for real-time databases and authentication.', 'استخدام خدمات جوجل السحابية لقواعد البيانات الفورية والتوثيق.', 'Backend', '#14f558', 85, 3),
  ('Git & GitHub', 'جيت و جيت هاب', 'Managing version control, source code repositories, and collaborative workflows.', 'إدارة النسخ الاحتياطية وإدارة الشيفرات البرمجية والعمل الجماعي باحترافية.', 'Tools', '#f05032', 90, 4),
  ('UI/UX Design', 'تصميم واجهات المستخدم', 'Designing engaging user experiences and clean interfaces for sites and apps.', 'تصميم تجارب مستخدم جذابة وواجهات واضحة للمواقع والتطبيقات.', 'Design', '#0040ff', 85, 5),
  ('Adobe Photoshop', 'فوتوشوب', 'Editing images and designing visual elements for websites and branding.', 'تعديل الصور وتصميم العناصر البصرية الخاصة بالمواقع والهوية.', 'Design', '#ff33b4', 85, 6),
  ('Photography', 'التصوير الفوتوغرافي', 'Capturing professional photos and integrating them visually into designs and projects.', 'التقاط صور احترافية وتوظيفها بصرياً في التصاميم والمشاريع.', 'Design', '#3100a3', 80, 7),
  ('Docker', 'دوكر', 'Containerizing applications to ensure seamless and consistent execution across different development and production environments.', 'عزل وتغليف التطبيقات داخل حاويات لضمان عملها بسلاسة وثبات عبر مختلف بيئات التطوير والإنتاج.', 'Tools', '#2496ed', 85, 8),
  ('Webpack', 'ويب باك', 'Bundling and optimizing frontend assets and modules to reduce application bundle size and improve loading performance.', 'تجميع وتحسين ملفات وموارد الواجهة الأمامية (جافاسكريبت، صور، أنماط) لتقليل حجم التطبيق ورفع كفاءة التحميل.', 'Tools', '#586b74', 80, 9),
  ('SEO', 'تحسين محركات البحث', 'Optimizing web architecture and metadata to improve search engine visibility and ranking.', 'تهيئة بنية الويب وهيكلة البيانات لرفع ظهور الموقع وتصدره في نتائج محركات البحث.', 'Performance', '#000000', 85, 10),
  ('Core Web Vitals', 'مؤشرات الأداء الأساسية للويب', 'Measuring and enhancing loading performance, visual stability, and interactivity for an optimal user experience.', 'قياس وتحسين سرعة الاستجابة، استقرار التخطيط البصري، وسرعة تحميل العناصر المرئية لتجربة مستخدم مثالية.', 'Performance', '#002e13', 90, 11),
  ('Lazy Loading', 'التحميل الكسول للموارد', 'Delaying the loading of non-critical images and assets until they enter the viewport to reduce initial load time and bandwidth usage.', 'تأجيل تحميل الصور والعناصر غير المرئية لحين الحاجة إليها لتقليل وقت التحميل الأولي واستهلاك النطاق الترددي.', 'Performance', '#ff9800', 95, 12),
  ('Vue.js', 'فيو جي إس', 'Developing fast and flexible Single Page Applications (SPAs) with efficient state management and reactive data binding.', 'تطوير تطبيقات ويب أحادية الصفحة (SPA) سريعة ومرنة مع إدارة فعالة لحالة التطبيق والربط التلقائي للبيانات.', 'Frontend', '#41b883', 85, 13),
  ('Tailwind CSS', 'تيلويند سي إس إس', 'Designing modern and responsive user interfaces directly using utility classes without writing massive traditional CSS files.', 'تصميم واجهات عصرية ومتجاوبة مباشرة من خلال فئات جاهزة ومخصصة دون الحاجة لكتابة ملفات CSS تقليدية ضخمة.', 'Frontend', '#ff8af5', 90, 14),
  ('TypeScript', 'تاييب سكريبت', 'Writing robust and maintainable JavaScript code by adding static typing to catch errors early during development.', 'كتابة كود جافاسكريبت آمن وقابل للصيانة عبر إضافة نظام الأنواع الثابتة (Static Types) لاكتشاف الأخطاء مبكراً.', 'Frontend', '#8cff00', 90, 15),
  ('Figma', 'فيجما', 'Designing interactive prototypes and engaging user interfaces with real-time collaboration capabilities and seamless transition to code.', 'تصميم نماذج أولية (Prototypes) تفاعلية وواجهات مستخدم جذابة مع القدرة على التعاون الحي وتحويل التصاميم إلى كود برمجي بسهولة.', 'Design', '#f24e1e', 85, 16),
  ('UI/UX Principles', 'مبادئ تصميم واجهات وتجربة المستخدم', 'Understanding user behavior, mapping user journeys, and applying core usability standards to deliver seamless digital experiences.', 'فهم سلوك المستخدمين، دراسة رحلة العميل (User Journey)، وتطبيق معايير سهولة الاستخدام (Usability) لتقديم تجربة سلسة.', 'Design', '#ffd500', 80, 17),
  ('Responsive Design', 'التصميم المتجاوب', 'Ensuring web interfaces adapt and render seamlessly across all screen sizes and devices (mobiles, tablets, and desktops).', 'ضمان توافق وتجاوب واجهات الويب بسلاسة مع جميع أحجام الشاشات والأجهزة المختلفة (هواتف، أجهزة لوحية، شاشات سطح المكتب).', 'Design', '#00c7b7', 95, 18);
insert into public.projects (name_en, name_ar, desc_en, desc_ar, category, tags_en, tags_ar, url, image, year, featured, sort_order, created_at) values
  ('Taif Al Arwo', 'طيف العرو', 'A professional portfolio platform enabling a lawyer to showcase advisory and legal services to clients, featuring a modern and user-friendly interface that allows visitors to book appointments and explore various legal specialties with confidence.', 'منصة تعريفية احترافية تتيح للمحامي عرض خدماته الاستشارية والقانونية للعملاء، مع واجهة عصرية وسهلة تتيح للزوار حجز المواعيد والتعرف على التخصصات القانونية المختلفة بثقة واحترافية.', 'Applications', array['Lawyer','Legal Consultation','Legal Services','Law Firm','Cases','Instant Consultation']::text[], array['محامي','استشارات قانونية','خدمات قانونية','محاماة','قضايا','استشارة فورية']::text[], 'https://taif-al-arwo.vercel.app/', 'https://i.postimg.cc/sfHqkyQz/Screenshot-2026-08-11-080222.png', 2026, true, 0, '2026-08-11T05:04:46.232819+00:00'),
  ('Comprehensive System Dashboard', 'نظام الإدارة الشامل', 'An advanced and comprehensive management dashboard designed to help businesses and individuals handle operations, monitor real-time data and analytics efficiently, featuring a fully responsive and seamless user experience.', 'لوحة تحكم إدارية متكاملة ومتطورة، مصممة خصيصاً لمساعدة الشركات والأفراد على إدارة العمليات، ومتابعة البيانات والإحصائيات الحية بسهولة وكفاءة عالية، مع دعم كامل لتجربة مستخدم سلسة ومتجاوبة مع كافة الشاشات.', 'Systems', array['Dashboard','Management','System','Analytics','UI/UX']::text[], array['لوحة تحكم','إدارة','نظام إداري','تحليل بيانات','واجهة مستخدم']::text[], 'https://system-coral-delta.vercel.app/', 'https://i.postimg.cc/6p2ct0dp/Screenshot-2026-08-08-060227.png', 2026, true, 1, '2026-08-08T03:04:27.230823+00:00'),
  ('Baba El Magal - Email Service', 'بابا المجال - خدمة البريد', 'A dedicated platform or tool for managing email services and notifications, designed to streamline communication and send messages in modern, professional layouts.', 'منصة أو أداة مخصصة لإدارة خدمات البريد الإلكتروني والإشعارات، مصممة لتسهيل التواصل وإرسال الرسائل بتنسيقات عصرية واحترافية.', 'Applications', array['Email Service','Tools','Communication','Email Templates','Notification System']::text[], array['بريد إلكتروني','أدوات','اتصال','قوالب رسائل','نظام إشعارات']::text[], 'https://baba-el-magal-email.vercel.app/', 'https://i.postimg.cc/Pxq98LSB/Screenshot-2026-08-04-091219.png', 2026, true, 2, '2026-08-04T06:14:22.081533+00:00'),
  ('Baba El Magal', 'بابا المجال', 'An interactive and modern web application carefully designed to deliver a seamless user experience with responsive interfaces and high performance built using cutting-edge technologies.', 'ويب تفاعلي ومميز، مصمم بعناية ليقدم تجربة مستخدم سلسة وعصرية مع واجهات متجاوبة وأداء عالي السرعة مبني باستخدام أحدث التقنيات.', 'E-Commerce', array['Web Apps','Interactive','UI/UX','React','Digital']::text[], array['تطبيقات ويب','تفاعلي','واجهة مستخدم','رياكت','ديجيتال']::text[], 'https://baba-el-magal.vercel.app/', 'https://i.postimg.cc/25n8XtmC/Screenshot-2026-08-04-090949.png', 2026, false, 3, '2026-08-04T06:11:34.363692+00:00'),
  ('Docline Clinic Dashboard', 'لوحة تحكم عيادات دوك لاين', 'A comprehensive dashboard and management system designed for medical clinics and healthcare centers. It enables doctors and administrators to efficiently manage appointments, patient records, settings, and medical services with a modern, fast, and responsive user interface.', 'نظام ولوحة تحكم متكاملة لإدارة العيادات الطبية والمراكز الصحية، تتيح للم پزشين وإداريي العيادات متابعة المواعيد، سجلات المرضى، الإعدادات، والخدمات الطبية بكل سهولة واحترافية مع واجهة مستخدم عصرية وسريعة.', 'Dashboards', array['Dashboard','Clinic Management','Appointments','Medical System','Docline','Healthcare']::text[], array['لوحة تحكم','إدارة عيادات','حجوزات','نظام طبي','دوك لاين','تفاصيل المواعيد']::text[], 'https://dashboard-docline.vercel.app/', 'https://i.postimg.cc/8cg57m1J/Screenshot-2026-08-03-063330.png', 2026, false, 4, '2026-08-03T03:38:34.525587+00:00'),
  ('Docline - Smart Document Management Platform', 'دوكلاين - منصة إدارة المستندات والخدمات الذكية', 'An advanced platform for managing and organizing documents and files with high efficiency, providing a secure and fast digital workflow environment to facilitate document review and management for users and businesses.', 'منصة متطورة لإدارة وتنظيم المستندات والملفات بكفاءة عالية، وتوفير بيئة عمل رقمية آمنة وسريعة لتسهيل مراجعة وإدارة الوثائق للمستخدمين والشركات.', 'Systems', array['Document Management','Smart System','Digital Archiving','File Organization','Web Platform']::text[], array['إدارة مستندات','نظام ذكي','أرشفة إلكترونية','تنظيم الملفات','منصة ويب']::text[], 'https://docline-dev74.vercel.app/', 'https://i.postimg.cc/pL3tVXVQ/Screenshot-2026-08-03-064402.png', 2026, false, 5, '2026-07-26T03:30:36.902249+00:00'),
  ('Sprylo - Next-Gen Tech & Electronics Store', 'سبرايلو - متجر الإلكترونيات والتقنية المستقبلية', 'A modern and advanced e-commerce platform dedicated to smartphones, tablets, and the latest wireless accessories and audio gear. It features a unique futuristic cyber design, seamless user interface, and a fast, secure shopping experience.', 'منصة تجارة إلكترونية عصرية ومتطورة مخصصة لبيع الهواتف الذكية، الأجهزة اللوحية، وأحدث الإكسسوارات والسماعات اللاسلكية. تتميز بتصميم سيبراني مستقبلي فريد، واجهة المستخدم السلسة، وتجربة تصفح سريعة وآمنة.', 'E-Commerce', array['E-Commerce','Technology','Smart Phones','Wireless Audio','Online Shopping','Exclusive Offers']::text[], array['متجر إلكتروني','تكنولوجيا','هواتف ذكية','سماعات لاسلكية','تسوق أونلاين','عروض حصرية']::text[], 'https://sprylo-peach.vercel.app/', 'https://i.postimg.cc/jjWdvF2Q/Screenshot-2026-08-03-064045.png', 2026, false, 6, '2026-07-26T03:29:13.575887+00:00'),
  ('Samhan Portfolio - Samhan Project', 'بورتفوليو سمحان - مشروع سمحان', 'A professional portfolio dedicated to showcasing the latest graphic design and visual identity projects. Features an elegant and engaging visual display highlighting creativity, color coordination, and UI/UX design skills.', 'معرض أعمال احترافي مخصص لعرض أحدث مشاريع التصميم الجرافيكي والهوية البصرية. يتميز بعرض مرئي أنيق وجذاب يبرز مهارات الابتكار وتنسيق الألوان وتصميم واجهات المستخدم.', 'Systems', array['Graphic Design','Visual Identity','UI/UX Design','Branding','Creative Art']::text[], array['تصميم جرافيكي','هوية بصرية','تصميم مرئي','واجهة مستخدم','إبداع فني']::text[], 'https://samhan10.vercel.app/', 'https://samhan74.vercel.app/assets/%D8%B3%D9%85%D8%AD%D8%A7%D9%86-YVJAfP1a.png', 2026, false, 7, '2026-07-26T01:00:07.218383+00:00'),
  ('Tabaakhuh Dashboard', 'لوحة تحكم طباخوه', 'A comprehensive administrative dashboard designed to efficiently manage the operations of the "Tabaakhuh" platform. The panel enables administrators to monitor orders, manage users and chefs, and view analytics and reports through a modern and user-friendly interface.', 'لوحة تحكم إدارية متكاملة مصممة لإدارة عمليات منصة "طباخوه" بكفاءة عالية. تتيح اللوحة للمadmins متابعة الطلبات، إدارة المستخدمين والطهاة، وعرض الإحصائيات والتقارير البيانية بواجهة مستخدم عصرية وسهلة الاستخدام.', 'Dashboards', array['Dashboard','Order Management','Analytics','Admin Panel','Management UI']::text[], array['لوحة تحكم','إدارة الطلبات','إحصائيات','لوحة قيادة','واجهة إدارة']::text[], 'https://tabaakhuh-ey12.vercel.app/', 'https://i.postimg.cc/J0R8w6rD/Screenshot-2026-08-03-064252.png', 2026, false, 8, '2026-07-26T00:58:02.103662+00:00'),
  ('Free Style', 'فري ستايل', 'A modern e-commerce store specialized in fashion and clothing, offering a diverse and contemporary collection of products that meet daily shopping needs in an elegant and seamless way.', 'تجر إلكتروني عصري متخصص في الأزياء والملابس، يقدم تشكيلة متنوعة وحديثة من المنتجات التي تلبي احتياجات التسوق اليومي بأسلوب أنيق وسلس.', 'E-Commerce', array['Fashion and Style','Modern Clothing','E-Commerce','Clothing Store','Free Style']::text[], array['أزياء وموضة','ملابس عصرية','تسوق إلكتروني','متجر ملابس','فري ستايل']::text[], 'https://free-style-7v85.vercel.app/', 'https://images.unsplash.com/photo-1542272604-787c3835535d?w=1600', 2026, false, 9, '2026-07-26T00:53:30.043389+00:00'),
  ('Homely', 'هوملي', 'An integrated e-commerce store dedicated to home products, furniture, and decor, allowing users to browse and purchase the latest products to furnish and decorate homes smoothly and easily.', 'متجر إلكتروني متكامل مخصص للمنتجات المنزلية والأثاث والديكور، يتيح للمستخدمين استصفاء وشراء أحدث المنتجات لتجهيز وتزيين المنازل بسهولة وسلاسة.', 'E-Commerce', array['Home Shopping','Furniture and Decor','Home Products','E-Commerce Store','Home Supplies']::text[], array['تسوق منزلي','أثاث وديكور','منتجات منزلية','متجر إلكتروني','مستلزمات المنزل']::text[], 'https://homely-lfyy.vercel.app/', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1920&q=80', 2026, false, 10, '2026-07-26T00:51:37.936564+00:00'),
  ('Pharaoh Code', 'فرعون كود', 'An interactive programming platform hosted on Vercel, designed to provide developers with tools and solutions to efficiently write and manage code and build modern applications.', 'منصة برمجية تفاعلية مستضافة على Vercel، تهدف إلى توفير أدوات وحلول للمطورين لتسهيل كتابة وادارة الأكواد البرمجية بكفاءة عالية وبناء التطبيقات الحديثة.', 'Applications', array['Development Tools','Web Development','Interactive Platform','Programming','Cloud Applications']::text[], array['أدوات برمجية','تطوير واجهات','منصة تفاعلية','برمجة','تطبيقات سحابية']::text[], 'https://pharaoh-code.vercel.app/', 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?q=80&w=1920', 2026, false, 11, '2026-07-26T00:49:09.884051+00:00'),
  ('Quran Application', 'تطبيق القرآن الكريم', 'An integrated Islamic web application for reading and listening to the Holy Quran, providing recitations by various reciters with the ability to browse Surahs and Ayahs with complete flexibility and ease.', 'تطبيق ويب إسلامي متكامل لقراءة واستماع القرآن الكريم، يوفر تلاوات بأسوات مختلف القراء، مع إمكانية تصفح السور والآيات بمرونة وسهولة تامة.', 'Applications', array['Holy Quran','Audio Recitations','E-Quran','Reading and Reflection','Islamic Applications']::text[], array['لقرآن الكريم','تلاوات صوتية','مصحف إلكتروني','قراءة وتدبر','تطبيقات إسلامية']::text[], 'https://quran-flax-eta.vercel.app/', 'https://images.unsplash.com/photo-1542816417-0983c9c9ad53?q=80&w=2070&auto=format&fit=crop', 2026, false, 12, '2026-07-26T00:46:12.791624+00:00'),
  ('Al-Ashbal Academy', 'أكاديمية الأشبال', 'An integrated platform for Al-Ashbal Sports Academy, aimed at developing the physical and mental skills of youth and juniors. The platform provides customized training programs for each age group, branch management, tournament displays, and a scouting platform to discover and develop talents towards professionalism.', 'منصة متكاملة لأكاديمية الأشبال الرياضية، تهدف إلى تطوير مهارات الناشئين والبراعم البدنية والذهنية. توفر المنصة خططاً تدريبية مخصصة لكل مرحلة سنية، وإدارة الفروع، وعرض البطولات، ومنصة كشفية لاكتشاف وتطوير المواهب نحو الاحتراف.', 'Applications', array['Sports Academy','Youth Training','Football','Training Programs','Sports Talents']::text[], array['أكاديمية رياضية','تدريب ناشئين','كرة قدم','برامج تدريبية','مواهب رياضية']::text[], 'https://al-ashbal.pages.dev/', 'https://res.cloudinary.com/dstlpavbf/image/upload/v1783637879/gbvo0zdplbxkolhrcuk4.jpg', 2026, false, 13, '2026-07-26T00:37:27.028707+00:00');
insert into public.experience (kind, title_en, title_ar, org_en, org_ar, period, desc_en, desc_ar, image, sort_order) values
  ('certificate', 'Certificate of Excellence in E-Marketing', 'شهادة تقدير في مجال التسويق الإلكتروني', 'Wolf Marketing & Advertising', 'وولف للتسويق والإعلان', 'من 12 أبريل إلى 19 أبريل 2022 (2022-04-12 to 2022-04-19)', 'Successfully passed the specialized course in E-Marketing with a "Very Good" grade, covering digital marketing fundamentals and effective promotion.', 'اجتياز الدورة الخاصة بمجال التسويق الإلكتروني بتقدير "جيد جداً"، وتغطي أساسيات التسويق الرقمي والترويج الفعّال.', '', 0),
  ('work', 'Web Developer Experience', 'خبرة مطور برمجيات وتطبيقات الويب', 'ART SOFT Development & Software', 'شركة آرت سوفت لتطوير البرمجيات', 'من 2022/1/1 إلى 2023/9/1', 'Work experience certificate as a Web Developer; including creating websites, developing company software, updating applications, and working efficiently within a team.', 'شهادة إثبات خبرة عمل في منصب مطور برمجيات عبر الإنترنت؛ شملت إنشاء مواقع إلكترونية، تطوير برمجيات الشركة، وتعديل وتحديث البرامج المستخدمة ضمن فريق عمل متكامل.', 'https://images.unsplash.com/photo-1523050854058-8df90110c9f1?q=80&w=1200&auto=format&fit=crop', 1),
  ('certificate', 'Full Stack Diploma', 'دبلومة التطوير الشامل (Full Stack)', 'Raya Academy / CompTIA', 'أكاديمية رايا / كومپتيا', 'مارس 2024 (MAR 2024)', 'Successfully completed the Full Stack Diploma, meeting all training program requirements certified by Raya Academy in collaboration with CompTIA.', 'إتمام دبلومة التطوير الشامل (Full Stack Diploma) بنجاح واستيفاء كافة متطلبات البرنامج التدريبي المعتمد من أكاديمية رايا بالتعاون مع CompTIA.', '', 2);
insert into public.services (title_en, title_ar, desc_en, desc_ar, icon, sort_order) values
  ('Websites & landing pages', 'مواقع وصفحات هبوط', 'Fast, responsive sites in React or Next.js, built to rank and convert.', 'مواقع سريعة ومتجاوبة بـ React أو Next.js، معمولة عشان تظهر في البحث وتجيب عملاء.', 'globe', 0),
